#include "aethon/compression/compressor.hpp"
#include "aethon/common/error.hpp"
namespace aethon::compression { namespace {
class NullCompressor final : public Compressor { public: protocol::CompressionMode mode() const noexcept override { return protocol::CompressionMode::none; } Bytes compress(std::span<const std::uint8_t> input) const override { return {input.begin(), input.end()}; } Bytes decompress(std::span<const std::uint8_t> input, std::size_t) const override { return {input.begin(), input.end()}; } };
class RleCompressor final : public Compressor { public: protocol::CompressionMode mode() const noexcept override { return protocol::CompressionMode::rle; } Bytes compress(std::span<const std::uint8_t> input) const override { Bytes out; for (std::size_t i = 0; i < input.size();) { auto value = input[i]; std::uint8_t run = 1; while (i + run < input.size() && input[i + run] == value && run < 255) ++run; out.push_back(run); out.push_back(value); i += run; } return out; } Bytes decompress(std::span<const std::uint8_t> input, std::size_t max_output) const override { if (input.size() % 2 != 0) throw Error(ErrorCode::malformed_packet, "malformed rle stream"); Bytes out; for (std::size_t i = 0; i < input.size(); i += 2) { auto run = input[i]; if (out.size() + run > max_output) throw Error(ErrorCode::malformed_packet, "rle output limit exceeded"); out.insert(out.end(), run, input[i + 1]); } return out; } };
} std::unique_ptr<Compressor> make_compressor(protocol::CompressionMode mode) { if (mode == protocol::CompressionMode::none) return std::make_unique<NullCompressor>(); if (mode == protocol::CompressionMode::rle) return std::make_unique<RleCompressor>(); throw Error(ErrorCode::invalid_argument, "unsupported compression mode"); } }
